5	/**
6	 * Membership level rule: a numeric level from 1 to 3 assigned on creation. It starts at 1, gains
7	 * 1 when the owner has an email address, gains 1 when the owner has no namesakes, and is capped at
8	 * 3 — level 4 is reserved for tenure.
9	 */
10	public final class MembershipLevel {
11	
12	    private static final int CAP = 3;
13	
14	    private MembershipLevel() {
15	    }
16	
17	    public static int of(Owner owner) {
18	        int level = 1;
19	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
20	            level++;
21	        }
22	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
23	            level++;
24	        }
25	        return Math.min(level, CAP);
26	    }
27	}
