7	/**
8	 * Derives an owner's {@code identityKey} = normalized telephone + '|' + (lower-cased email or
9	 * empty) + '|' + household id. Duplicate detection is a single equality on this whole key, and it
10	 * is also returned on the owner. Two owners collide only when telephone, email and household all
11	 * match; sharing only a household (with different telephones) yields different keys.
12	 */
13	public final class IdentityKey {
14	
15	    private IdentityKey() {
16	    }
17	
18	    public static String of(Owner owner) {
19	        String email = owner.getEmail() == null || owner.getEmail().isBlank()
20	                ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
21	        return owner.getTelephone() + "|" + email + "|" + owner.getHouseholdId();
22	    }
23	}
