1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.Map;
4	
5	/**
6	 * Maps a city to its canonical region using a fixed city-to-region table.
7	 */
8	public final class Locality {
9	
10	    private static final Map<String, String> REGIONS = Map.of(
11	        "Sydney", "NSW",
12	        "Melbourne", "VIC",
13	        "Brisbane", "QLD");
14	
15	    private Locality() {
16	    }
17	
18	    /**
19	     * Returns the canonical region for the given city, or {@code "UNKNOWN"} when the city
20	     * is not in the table.
21	     */
22	    public static String of(String city) {
23	        return REGIONS.getOrDefault(city, "UNKNOWN");
24	    }
25	
26	    /**
27	     * Returns the canonical region, preferring the postcode range (NSW 2000-2099,
28	     * VIC 3000-3099, QLD 4000-4099) and falling back to the city-to-region table when the
29	     * postcode is absent or in no known range.
30	     */
31	    public static String of(String city, String postcode) {
32	        String byPostcode = byPostcode(postcode);
33	        return byPostcode != null ? byPostcode : of(city);
34	    }
35	
36	    private static String byPostcode(String postcode) {
37	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
38	            return null;
39	        }
40	        int code = Integer.parseInt(postcode);
41	        if (code >= 2000 && code <= 2099) {
42	            return "NSW";
43	        }
44	        if (code >= 3000 && code <= 3099) {
45	            return "VIC";
46	        }
47	        if (code >= 4000 && code <= 4099) {
48	            return "QLD";
49	        }
50	        return null;
51	    }
52	}
