1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	import java.util.Map;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Locality;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.MissingFieldsException;
10	
11	/**
12	 * Validates an owner's optional postcode when present: it must be four digits and, when the city's
13	 * region is known, fall within that region's fixed range (NSW 2000-2099, VIC 3000-3099,
14	 * QLD 4000-4099). A city with no known region accepts any 4-digit postcode. An absent postcode is
15	 * left untouched, keeping the create request backward-compatible. A bad postcode is a 400 via
16	 * {@link MissingFieldsException}.
17	 */
18	public class ValidatePostcode {
19	
20	    /** Region -> inclusive {low, high} 4-digit postcode range. */
21	    private static final Map<String, int[]> REGION_RANGES = Map.of(
22	        "NSW", new int[] {2000, 2099},
23	        "VIC", new int[] {3000, 3099},
24	        "QLD", new int[] {4000, 4099});
25	
26	    public void service(@Val OwnerFieldsDto request) throws MissingFieldsException {
27	        String postcode = request.getPostcode();
28	        if (postcode == null) {
29	            return;
30	        }
31	        int[] range = REGION_RANGES.get(Locality.of(request.getCity()));
32	        if (!postcode.matches("[0-9]{4}") || (range != null
33	                && (Integer.parseInt(postcode) < range[0] || Integer.parseInt(postcode) > range[1]))) {
34	            throw new MissingFieldsException(List.of("postcode"));
35	        }
36	    }
37	}
