14	
15	    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
16	        Owner owner = ownerMapper.toOwner(request);
17	        LocalDate date = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
18	        if (date.getDayOfWeek().getValue() > 5) { // Saturday or Sunday: roll forward to Monday
19	            date = date.with(TemporalAdjusters.next(DayOfWeek.MONDAY));
20	        }
21	        owner.setRegistrationDate(date);
22	        built.set(owner);
23	    }
